mapper.select:
SELECT channel, target, code, expires_at, verified_at, last_requested_at, attempt_count
  FROM MEMBER_SIGNUP_VERIFICATIONS
 WHERE channel = #{channel}
   AND target = #{target}

mapper.delete:
DELETE FROM MEMBER_SIGNUP_VERIFICATIONS
 WHERE channel = #{channel}
   AND target = #{target}

DELETE FROM MEMBER_SIGNUP_VERIFICATIONS
 WHERE expires_at IS NOT NULL
   AND expires_at < #{now}
